iterations.rule_text:
{
 "title": "AdFind Suspicious Command Line Switches",
 "description": "Detects execution of adfind.exe with specific command-line switches that are commonly used for Active Directory reconnaissance.",
 "tags": [
  "attack.discovery",
  "attack.t1087"
 ],
 "logsource_category": "process_creation",
 "groups": [
  {
   "name": "selection",
   "fields": [
    {
     "field": "CommandLine|re",
     "modifier": "re",
     "values": [
      "(?:^|\\\\s)(-kdsrootkeys|-csvbreakcount|-onlygroup|-whoami|-decattid|-enccurrentutcgt|-encutcgt|-outputcurrentint8|-outputcurrentgt|-jwdsinit|-jwdsstd|-jwdsstdro|-default|-s)(?=\\\\s|$)"
     ]
    }
   ]
  },
  {
   "name": "filter",
   "fields": []
  }
 ],
 "condition": "selection",
 "falsepositives": [
  "Legitimate administrative use of AdFind for authorized directory queries."
 ],
 "level": "high"
}

